create or replace function public.get_organization_nominee_analytics(p_org uuid) returns table(nominee_id uuid,nominee_name text,event_name text,category_name text,total_votes bigint,paid_votes bigint) language sql stable security definer set search_path='' as $$ select n.id,n.name,e.name,c.name,coalesce(sum(case when b.payment_attempt_id is null then b.quantity else greatest(0,b.quantity-ceil(coalesce(l.refunded_amount_minor,0)::numeric/nullif(p.unit_price_minor,0))) end),0)::bigint,coalesce(sum(case when b.payment_attempt_id is null then 0 else greatest(0,b.quantity-ceil(coalesce(l.refunded_amount_minor,0)::numeric/nullif(p.unit_price_minor,0))) end),0)::bigint from public.nominees n join public.categories c on c.id=n.category_id join public.events e on e.id=c.event_id left join public.vote_batches b on b.nominee_id=n.id left join public.payment_attempts p on p.id=b.payment_attempt_id left join public.paid_vote_ledger l on l.reference=p.provider_reference where e.organization_id=p_org and private.is_org_member(p_org) group by n.id,n.name,e.name,c.name order by 5 desc limit 100; $$;
revoke all on function public.get_organization_nominee_analytics(uuid) from public,anon; grant execute on function public.get_organization_nominee_analytics(uuid) to authenticated;
create or replace function public.get_organization_vote_trends(p_org uuid,p_days integer default 30) returns table(day date,total_votes bigint,free_votes bigint,paid_votes bigint) language sql stable security definer set search_path='' as $$ select b.created_at::date,sum(b.quantity)::bigint,sum(case when b.payment_attempt_id is null then b.quantity else 0 end)::bigint,sum(case when b.payment_attempt_id is null then 0 else b.quantity end)::bigint from public.vote_batches b join public.events e on e.id=b.event_id where e.organization_id=p_org and private.is_org_member(p_org) and b.created_at>=current_date-greatest(1,least(p_days,365)) group by b.created_at::date order by 1; $$;
revoke all on function public.get_organization_vote_trends(uuid,integer) from public,anon; grant execute on function public.get_organization_vote_trends(uuid,integer) to authenticated;


